INSERT INTO ar_landforms (id, name, description, type, image_url, elevation, is_active, created_at, noise_seed, noise_type, scale, amplitude, octaves, persistence, knowledge_content, labels) VALUES
('a0000001-0000-0000-0000-000000000001', '山峰', '高海拔地形', 'MOUNTAIN', '', 8848, TRUE, NOW(), 42, 'MOUNTAIN', 3, 2.5, 4, 0.5, '山峰是地球表面高出周围地区的隆起地形。世界最高峰是珠穆朗玛峰，海拔8848米。\n山峰通常由地壳运动形成，包括褶皱山、断块山和火山等类型。', '[{"id":"peak","name":"峰顶","position":{"x":0,"y":2.0,"z":0}}]'),
('a0000001-0000-0000-0000-000000000002', '盆地', '洼地地形', 'BASIN', '', 1240, TRUE, NOW(), 123, 'BASIN', 3, 1.5, 3, 0.4, '盆地是四周高、中间低的地形，如四川盆地、塔里木盆地。\n盆地底部通常较为平坦，适合人类居住和农业生产。', '[{"id":"bottom","name":"盆地底部","position":{"x":0,"y":-0.8,"z":0}}]'),
('a0000001-0000-0000-0000-000000000003', '山谷', '河流路径', 'VALLEY', '', 500, TRUE, NOW(), 456, 'VALLEY', 3, 1.2, 4, 0.5, '山谷是两山之间的低洼地带，常有河流经过。\n山谷分为V形谷和U形谷，分别由河流和冰川侵蚀形成。', '[{"id":"floor","name":"谷底","position":{"x":-3,"y":-0.3,"z":0}}]'),
('a0000001-0000-0000-0000-000000000004', '高原', '平坦高地', 'PLATEAU', '', 3000, TRUE, NOW(), 789, 'PLATEAU', 4, 1.0, 3, 0.3, '高原是海拔较高、顶面平坦开阔的地形。\n世界上最大的高原是巴西高原，最高的高原是青藏高原。', '[{"id":"surface","name":"高原面","position":{"x":0,"y":0.5,"z":0}}]'),
('a0000001-0000-0000-0000-000000000005', '悬崖', '垂直落差', 'CLIFF', '', 900, TRUE, NOW(), 101, 'CLIFF', 3, 2.0, 3, 0.4, '悬崖是坡度极陡的岩石地形，常见于海岸和山区。\n悬崖的形成通常与侵蚀作用和地质断裂有关。', '[{"id":"wall","name":"崖壁","position":{"x":0,"y":0.3,"z":0}}]');
